// Party Combos: a chain of Skill Box skills, each run by a subagent, which the
// main model leads. A combo is waves (`layers`) run one after another; every
// step of a wave is fanned out at once, and the next wave waits for them all.
// After a wave, an optional condition tells the leader what to do with what came
// back (report and stop, go on, …), in the person's own words.

export const COMBO_MODELS = ['haiku', 'sonnet', 'opus', 'fable'] as const
export type ComboModel = (typeof COMBO_MODELS)[number]

// The built-in subagent types a step can take, in the order a press cycles
// them; the person's own agents follow.
export const DEFAULT_AGENTS = ['general-purpose', 'Explore', 'Plan'] as const

// The engine's other agents each do one job of their own (Claude Code's docs,
// the status line) or repeat general-purpose, and run no skill: never offered.
const NOT_FOR_STEPS = ['claude', 'claude-code-guide', 'statusline-setup']

// Whether a subagent type the session offers can take a step: the person's own
// and plugins' agents can; of the built-ins, those above already are.
export const forSteps = (agent: string, source: string): boolean =>
  source !== 'built-in' && !NOT_FOR_STEPS.includes(agent) && !(DEFAULT_AGENTS as readonly string[]).includes(agent)

// How a step shows its subagent type: the built-ins short and lower case.
export const agentLabel = (agent: string): string =>
  agent === 'general-purpose' ? 'general' : (DEFAULT_AGENTS as readonly string[]).includes(agent) ? agent.toLowerCase() : agent

export type ComboStep = { skill: string; model: ComboModel; agent: string }
export type ComboLayer = { steps: ComboStep[]; condition?: string }
export type Combo = { name: string; layers: ComboLayer[] }

export const COMBO_CATEGORY = 'Party Combo'

const isModel = (v: unknown): v is ComboModel => COMBO_MODELS.includes(v as ComboModel)

// What the store kept, with anything unreadable dropped and names made unique.
export function combosFrom(kept: unknown): Combo[] {
  if (!Array.isArray(kept)) return []
  const out: Combo[] = []
  for (const c of kept) {
    if (!c || typeof c !== 'object' || typeof c.name !== 'string' || !c.name.trim()) continue
    if (out.some(o => o.name === c.name)) continue
    const layers: ComboLayer[] = (Array.isArray(c.layers) ? c.layers : []).flatMap((l: unknown): ComboLayer[] => {
      if (!l || typeof l !== 'object') return []
      const { steps, condition } = l as ComboLayer
      const kept: ComboStep[] = (Array.isArray(steps) ? steps : []).flatMap((s: unknown): ComboStep[] => {
        if (!s || typeof s !== 'object') return []
        const { skill, model, agent } = s as ComboStep
        if (typeof skill !== 'string' || !skill) return []
        return [{ skill, model: isModel(model) ? model : 'haiku', agent: typeof agent === 'string' && agent ? agent : DEFAULT_AGENTS[0] }]
      })
      return [{ steps: kept, ...(typeof condition === 'string' && condition.trim() ? { condition } : {}) }]
    })
    out.push({ name: c.name, layers })
  }
  return out
}

// A fresh combo's name: `Combo 1`, `Combo 2`, … the first not taken.
export function newComboName(combos: readonly Combo[]): string {
  for (let n = 1; ; n++) if (!combos.some(c => c.name === `Combo ${n}`)) return `Combo ${n}`
}

// A name for a rename: trimmed, and refused when empty or another's.
export function renameOk(combos: readonly Combo[], from: string, to: string): string | undefined {
  const name = to.trim().replace(/\s+/g, ' ')
  if (!name || (name !== from && combos.some(c => c.name === name))) return undefined
  return name
}

const swap = <T>(list: readonly T[], at: number, by: -1 | 1): T[] => {
  const to = at + by
  if (at < 0 || at >= list.length || to < 0 || to >= list.length) return [...list]
  const next = [...list]
  next[at] = list[to]!
  next[to] = list[at]!
  return next
}

// The edits the Party Combo section makes, each giving a new combo.
export const addLayer = (c: Combo): Combo => ({ ...c, layers: [...c.layers, { steps: [] }] })
export const moveLayer = (c: Combo, at: number, by: -1 | 1): Combo => ({ ...c, layers: swap(c.layers, at, by) })
export const removeLayer = (c: Combo, at: number): Combo => ({ ...c, layers: c.layers.filter((_, i) => i !== at) })

const editLayer = (c: Combo, at: number, fn: (l: ComboLayer) => ComboLayer): Combo => ({
  ...c,
  layers: c.layers.map((l, i) => (i === at ? fn(l) : l)),
})

export const addStep = (c: Combo, layer: number, skill: string): Combo =>
  editLayer(c, layer, l => ({ ...l, steps: [...l.steps, { skill, model: 'haiku', agent: DEFAULT_AGENTS[0] }] }))

export const removeStep = (c: Combo, layer: number, step: number): Combo =>
  editLayer(c, layer, l => ({ ...l, steps: l.steps.filter((_, i) => i !== step) }))

const editStep = (c: Combo, layer: number, step: number, fn: (s: ComboStep) => ComboStep): Combo =>
  editLayer(c, layer, l => ({ ...l, steps: l.steps.map((s, i) => (i === step ? fn(s) : s)) }))

// The step's next model, round the families.
export const cycleModel = (c: Combo, layer: number, step: number): Combo =>
  editStep(c, layer, step, s => ({ ...s, model: COMBO_MODELS[(COMBO_MODELS.indexOf(s.model) + 1) % COMBO_MODELS.length]! }))

// The step's next subagent type, round those offered (from the first, when
// its own is no longer one of them).
export const cycleAgent = (c: Combo, layer: number, step: number, agents: readonly string[]): Combo =>
  editStep(c, layer, step, s => ({ ...s, agent: agents[(agents.indexOf(s.agent) + 1) % agents.length] ?? s.agent }))

export const setCondition = (c: Combo, layer: number, text: string): Combo =>
  editLayer(c, layer, l => {
    const { condition: _, ...rest } = l
    return text.trim() ? { ...rest, condition: text } : rest
  })

// What a combo holds, dim after its button in the Skill Box: `2 layers · 3 skills`.
export function comboSummary(c: Combo): string {
  const steps = c.layers.reduce((n, l) => n + l.steps.length, 0)
  const layers = c.layers.filter(l => l.steps.length > 0).length
  return `${layers} wave${layers === 1 ? '' : 's'} · ${steps} skill${steps === 1 ? '' : 's'}`
}

// The tag each Agent call's description starts with, so a step can be told
// apart: `[Run-Test #3 2.1]`, `#3` the press (Dungeon's mission) it is of,
// when the press has one.
export const stepTag = (combo: string, layer: number, step: number, mission?: number) =>
  `[${combo}${mission === undefined ? '' : ` #${mission}`} ${layer + 1}.${step + 1}]`

// The model a combo's leader runs on: a subagent of its own, so the person's
// conversation is never the one that leads it.
export const LEADER_MODEL: ComboModel = 'sonnet'

// The tool a combo's subagents ask the person with (served by register.tsx):
// the question shows on the step's card in Dungeon, and the answer comes back
// as the tool's result.
export const ASK_TOOL_NAME = 'ask_person'
export const ASK_TOOL = `mcp__slime-dashboard__${ASK_TOOL_NAME}`

// The description a leader's Agent call starts with: `[Run-Test #3] lead`.
export const leaderTag = (combo: string, mission: number) => `[${combo} #${mission}] lead`

// The prompt the leader gets to lead the combo: every layer in order, its
// steps fanned out at once with the model and subagent type each names, and
// the conditions to judge after a layer. Empty layers are skipped; a combo
// with no step at all has nothing to run. `mission` numbers this press;
// `subagent` says the leader is one, which waits on each step in the
// foreground and answers with the report.
export function comboPrompt(combo: Combo, input: string, mission?: number, subagent = false): string | undefined {
  const layers = combo.layers.filter(l => l.steps.length > 0)
  if (layers.length === 0) return undefined
  const lines = [
    `Run the Party Combo "${combo.name}"${mission === undefined ? '' : ` (mission #${mission})`}. You lead it: hand each step below to a subagent with the Agent tool, with exactly the model and subagent_type it names, and do not do a step's work yourself.`,
    'Run the waves in order. Dispatch every step of a wave at once, as parallel Agent calls in one message, and wait for all of them to report before you go on. Begin each Agent call\'s description with the step\'s tag. Tell each subagent to run its skill (the Skill tool, or the slash command) and report what came of it, and pass on the input and whatever earlier steps found that it needs.' +
      (subagent
        ? ' However the Agent tool runs them, wait for every report of a wave before you go on. A step the person stopped is not run again: take it as failed, and judge the condition on that.' +
          ` Tell each subagent too: whatever it sends out (a subagent, a background command), it waits for before it reports; and where its skill would ask the person something, it asks with the ${ASK_TOOL} tool and waits for the answer, never guessing it. Ask the person that way yourself, if you must.`
        : ''),
    '',
    `Input: ${input.trim() || '(none)'}`,
  ]
  combo.layers.forEach((layer, i) => {
    if (layer.steps.length === 0) return
    lines.push('', `Wave ${i + 1}${layer.steps.length > 1 ? ' (all at once)' : ''}:`)
    layer.steps.forEach((s, j) => lines.push(`- ${stepTag(combo.name, i, j, mission)} skill /${s.skill}, model ${s.model}, subagent_type ${s.agent}`))
    if (layer.condition?.trim()) lines.push(`Then, before anything else, judge what came back: ${layer.condition.trim()}`)
  })
  lines.push('', subagent ? 'When the combo ends, answer with each step\'s result in a line or two, and which waves did not run and why.' : 'When the combo ends, report each step\'s result in a line or two.')
  return lines.join('\n')
}

files.hooks/squad.ts:
// Dungeon: what each Party Combo sent has done. A mission is one press of
// a combo: its waves and steps as they stood then, and for each step the
// subagent that took it, known by the tag its Agent call's description starts
// with (combos.ts' stepTag). A subagent of the combo's turn whose tag names no
// step (the leader left it out, or added a task of its own) is kept apart.
// Kept in this session's memory only.

import type { Combo, ComboModel } from './combos'

export type RunStatus = 'running' | 'completed' | 'failed' | 'stopped'

// One subagent: what it was asked, and how far it has got.
export type SquadRun = {
  id: string
  description: string
  model?: string
  status: RunStatus
  // Its model requests so far, and the tool it called last.
  steps: number
  tool?: string
  // The tokens its model requests have taken in and given out so far; and as
  // its turns' ends reported them, where its requests carried none.
  tokens?: number
  turnTokens?: number
  // Its final answer, once it gave one.
  result?: string
  startedAt: number
  endedAt?: number
  // It sent work to the background this turn (a shell, a monitor): its turn's
  // end then leaves it `awaiting` that work, still running, not done.
  background?: boolean
  awaiting?: boolean
  // A question it put to the person (the ask_person tool), until answered.
  asking?: Ask
}

export type Ask = { question: string; options?: string[] }

// `helpers`: the subagents the step's own sent out (its skill dispatching
// them), or that took its tag again: the same step's work.
export type SquadStep = { skill: string; model: ComboModel; agent: string; run?: SquadRun; helpers?: SquadRun[] }
// `n` is the wave's number in the combo, as its steps' tags count it.
export type SquadWave = { n: number; condition?: string; steps: SquadStep[] }

export type Mission = {
  id: number
  combo: string
  sentAt: number
  // When the leader's turn took up the combo, and when that turn ended (and how).
  begunAt?: number
  endedAt?: number
  outcome?: 'done' | 'stopped' | 'error'
  // Called back whole by the person (Dungeon's [Recall]).
  recalled?: boolean
  // The Skill Box's prompt it was sent with, for a run again.
  input?: string
  waves: SquadWave[]
  others: SquadRun[]
  // The subagent leading it, when one does (else the person's own model did).
  leader?: SquadRun
}

// A press of `combo` (with `input`): its waves with a step in them, none of
// them run yet.
export function newMission(id: number, combo: Combo, at: number, input?: string): Mission {
  const waves = combo.layers.flatMap((layer, i): SquadWave[] =>
    layer.steps.length === 0
      ? []
      : [{ n: i + 1, ...(layer.condition?.trim() ? { condition: layer.condition.trim() } : {}), steps: layer.steps.map(s => ({ ...s })) }],
  )
  return { id, combo: combo.name, sentAt: at, waves, others: [], ...(input?.trim() ? { input } : {}) }
}

// The combo a mission was a press of, as it stood then: its waves at their
// numbers (the empty ones between them empty again), for a run again.
export function missionCombo(m: Mission): Combo {
  const last = Math.max(0, ...m.waves.map(w => w.n))
  const layers = Array.from({ length: last }, (_, i) => {
    const w = m.waves.find(x => x.n === i + 1)
    return w ? { steps: w.steps.map(({ skill, model, agent }) => ({ skill, model, agent })), ...(w.condition ? { condition: w.condition } : {}) } : { steps: [] }
  })
  return { name: m.combo, layers }
}

export type Tag = { combo: string; mission?: number; wave: number; step: number }

// `[Run-Test #3 2.1] run the tests` to the combo, mission, wave and step it
// names (`[Run-Test 2.1]`, a tag without the mission, as well).
export function tagOf(description: string): Tag | undefined {
  const m = description.match(/^\s*\[(.+?)(?: #(\d+))? (\d+)\.(\d+)\]/)
  return m ? { combo: m[1]!, ...(m[2] ? { mission: Number(m[2]) } : {}), wave: Number(m[3]), step: Number(m[4]) } : undefined
}

// The prompt a combo sends starts with its name and its mission's number
// (combos.ts' comboPrompt). Prompts sent while the leader was busy reach it as
// one, each on a line of its own: every one named so.
export function combosOf(prompt: string): { combo: string; mission?: number }[] {
  return [...prompt.matchAll(/^Run the Party Combo "(.+?)"(?: \(mission #(\d+)\))?\./gm)].map(m => ({
    combo: m[1]!,
    ...(m[2] ? { mission: Number(m[2]) } : {}),
  }))
}

// The number the next press's mission takes: past every one so far, and past
// `last`, the last one handed out (a mission taken off keeps its number used).
export const nextMissionId = (missions: readonly Mission[], last: number): number =>
  Math.max(last, ...missions.map(m => m.id)) + 1

// `[Run-Test #3] lead` to the combo and mission it leads (combos.ts' leaderTag).
export function leaderOf(description: string): { combo: string; mission: number } | undefined {
  const m = description.match(/^\s*\[(.+?) #(\d+)\] lead\b/)
  return m ? { combo: m[1]!, mission: Number(m[2]) } : undefined
}

const isLive = (m: Mission) => m.begunAt !== undefined && m.endedAt === undefined

// The leader's turn took up `combo`: the mission its prompt numbers, else its
// oldest mission not yet begun, begins.
export function beginMission(missions: readonly Mission[], combo: string, at: number, mission?: number): Mission[] {
  const i = missions.findIndex(m => m.combo === combo && m.begunAt === undefined && (mission === undefined || m.id === mission))
  return i < 0 ? [...missions] : missions.map((m, k) => (k === i ? { ...m, begunAt: at } : m))
}

// The leader's turn ended: its missions end with it, but for one with a
// subagent still running. A step run in the background lets the leader's turn
// end at once, and the leader takes the mission up again when it reports.
// A mission with a leader of its own is not the person's turn's: it ends with
// its leader (endLed).
export function endMissions(missions: readonly Mission[], outcome: Mission['outcome'], at: number): Mission[] {
  return missions.map(m => (isLive(m) && !m.leader && !runsOf([m]).some(r => r.status === 'running') ? { ...m, endedAt: at, outcome } : m))
}

// Whether any mission is still going: Dungeon's clock then keeps ticking.
export const anyLive = (missions: readonly Mission[]): boolean => missions.some(isLive)

// A step's run to its mission: to the step if still free, else among its
// others. The mission goes on (begun, or taken up again) while it runs.
function attachTo(missions: readonly Mission[], i: number, tag: Tag, run: SquadRun): Mission[] {
  return missions.map((m, k) => {
    if (k !== i) return m
    const { endedAt: _, outcome: __, ...rest } = m
    const going = { ...rest, begunAt: m.begunAt ?? run.startedAt }
    const wave = m.waves.find(w => w.n === tag.wave)
    const step = wave?.steps[tag.step - 1]
    if (!wave || !step) return { ...going, others: [...m.others, run] }
    const took = (s: SquadStep): SquadStep => (s.run ? { ...s, helpers: [...(s.helpers ?? []), run] } : { ...s, run })
    return { ...going, waves: m.waves.map(w => (w !== wave ? w : { ...w, steps: w.steps.map(s => (s !== step ? s : took(s))) })) }
  })
}

// A subagent started. A leader's goes to the mission it leads, which begins.
// One a step's subagent (or its helper) spawned (`parent`) is that step's
// helper. A tag with a mission's number goes to that mission, and only there
// (a step already taken: its helper). A subagent one of a mission's own
// spawned otherwise is among its others.
// Else, a tag without a number: to the step it names in the newest live
// mission of that combo whose step is still free (a press never seen taken up
// begins first); else, while a mission is live, among the newest one's others.
// Undefined when it is no mission's: not the squad's.
export function attachRun(missions: readonly Mission[], run: SquadRun, parent?: string): Mission[] | undefined {
  const leads = leaderOf(run.description)
  if (leads) {
    const i = missions.findIndex(m => m.id === leads.mission && m.combo === leads.combo)
    if (i >= 0) {
      return missions.map((m, k) => {
        if (k !== i) return m
        const { endedAt: _, outcome: __, ...rest } = m
        return { ...rest, begunAt: m.begunAt ?? run.startedAt, leader: run }
      })
    }
  }
  if (parent !== undefined) {
    for (let i = 0; i < missions.length; i++) {
      const m = missions[i]!
      const step = m.waves.flatMap(w => w.steps).find(s => [...(s.run ? [s.run] : []), ...(s.helpers ?? [])].some(r => r.id === parent))
      if (!step) continue
      const { endedAt: _, outcome: __, ...rest } = m
      return missions.map((x, k) =>
        k !== i ? x : { ...rest, waves: m.waves.map(w => ({ ...w, steps: w.steps.map(s => (s !== step ? s : { ...s, helpers: [...(s.helpers ?? []), run] })) })) },
      )
    }
  }
  const tag = tagOf(run.description)
  if (tag?.mission !== undefined) {
    const i = missions.findIndex(m => m.id === tag.mission && m.combo === tag.combo)
    if (i >= 0) return attachTo(missions, i, tag, run)
  }
  if (parent !== undefined) {
    const i = missions.findIndex(m => runsOf([m]).some(r => r.id === parent))
    if (i >= 0) {
      return missions.map((m, k) => {
        if (k !== i) return m
        const { endedAt: _, outcome: __, ...rest } = m
        return { ...rest, others: [...m.others, run] }
      })
    }
  }
  if (tag && !missions.some(m => isLive(m) && m.combo === tag.combo) && missions.some(m => m.combo === tag.combo && m.begunAt === undefined))
    missions = beginMission(missions, tag.combo, run.startedAt)
  for (let i = missions.length - 1; tag && i >= 0; i--) {
    const m = missions[i]!
    if (!isLive(m) || m.combo !== tag.combo) continue
    const wave = m.waves.find(w => w.n === tag.wave)
    const step = wave?.steps[tag.step - 1]
    if (!wave || !step || step.run) continue
    return missions.map((x, k) =>
      k !== i ? x : { ...x, waves: x.waves.map(w => (w !== wave ? w : { ...w, steps: w.steps.map(s => (s !== step ? s : { ...s, run })) })) },
    )
  }
  for (let i = missions.length - 1; i >= 0; i--) {
    if (isLive(missions[i]!)) return missions.map((x, k) => (k === i ? { ...x, others: [...x.others, run] } : x))
  }
  return undefined
}

// The run under `id` changed; undefined when no mission holds it.
export function updateRun(missions: readonly Mission[], id: string, fn: (r: SquadRun) => SquadRun): Mission[] | undefined {
  let found = false
  const edit = (r: SquadRun) => {
    if (r.id !== id) return r
    found = true
    return fn(r)
  }
  const next = missions.map(m => mapRuns(m, edit))
  return found ? next : undefined
}

// Every run in the missions: leaders, steps, their helpers and others alike.
export const runsOf = (missions: readonly Mission[]): SquadRun[] =>
  missions.flatMap(m => [...(m.leader ? [m.leader] : []), ...m.waves.flatMap(w => w.steps.flatMap(stepRuns)), ...m.others])

// A step's runs: its own subagent's, then its helpers'.
export const stepRuns = (s: SquadStep): SquadRun[] => [...(s.run ? [s.run] : []), ...(s.helpers ?? [])]

// How a step stands: running while its subagent or any helper it sent out
// still runs (or awaits its background work); else as its own subagent ended.
// Undefined until a subagent took it.
export function stepStatus(s: SquadStep): RunStatus | undefined {
  if (!s.run) return undefined
  return stepRuns(s).some(r => r.status === 'running') ? 'running' : s.run.status
}

// The run of a step (or any run) that waits on the person's answer.
export const askingRun = (runs: readonly SquadRun[]): SquadRun | undefined => runs.find(r => r.asking !== undefined && r.status === 'running')

export type MissionState = 'queued' | 'running' | 'asking' | 'done' | 'stopped' | 'recalled' | 'error'

// How a mission stands, as its folded card says it.
export function missionState(m: Mission): MissionState {
  if (m.endedAt !== undefined) return m.recalled ? 'recalled' : (m.outcome ?? 'done')
  if (askingRun(runsOf([m]))) return 'asking'
  return m.begunAt === undefined ? 'queued' : 'running'
}

// The missions cleared (ended done) this session, by number: `cleared` with
// any newly done added; undefined when none is new.
export function clearedOf(missions: readonly Mission[], cleared: readonly number[]): number[] | undefined {
  const fresh = missions.filter(m => m.endedAt !== undefined && m.outcome === 'done' && !cleared.includes(m.id)).map(m => m.id)
  return fresh.length > 0 ? [...cleared, ...fresh] : undefined
}

// The agents a mission's subagents spawned that Dungeon has not seen start
// (`agents` as the engine lists them), and the model each runs on as far as
// its step says, else `fallback`.
export function agentsToFollow(missions: readonly Mission[], agents: readonly { id: string; description: string; parentId?: string }[], fallback: string) {
  const known = new Set(runsOf(missions).map(r => r.id))
  return agents.flatMap(a => {
    if (known.has(a.id) || a.parentId === undefined || !known.has(a.parentId)) return []
    const tag = tagOf(a.description)
    const m = missions.find(x => runsOf([x]).some(r => r.id === a.parentId))
    const step = tag && m?.combo === tag.combo ? m.waves.find(w => w.n === tag.wave)?.steps[tag.step - 1] : undefined
    const parent = step ? undefined : runsOf(missions).find(r => r.id === a.parentId)
    return [{ id: a.id, description: a.description, parentId: a.parentId, model: step?.model ?? (parent && !leaderOf(parent.description) ? parent.model : undefined) ?? fallback }]
  })
}

// How long a mission whose leader ended its turn stays quiet (nothing running)
// before it counts as done: a leader waiting on its steps' reports ends its
// turn between waves, and is woken to send the next.
export const SETTLE_MS = 10_000

// When the last run of a mission ended.
const lastEnd = (m: Mission) => Math.max(0, ...runsOf([m]).map(r => r.endedAt ?? 0))

// Whether a mission that finished done has been quiet long enough to be done:
// a stop or a failure is not waited on.
const calm = (m: Mission, outcome: Mission['outcome'], at: number) => outcome !== 'done' || at - lastEnd(m) >= SETTLE_MS

// When a mission that ended is said to have: a done one, when its last run
// ended (the quiet it waited out is no work); else now.
const endOf = (m: Mission, outcome: Mission['outcome'], at: number) => (outcome === 'done' && lastEnd(m) > 0 ? lastEnd(m) : at)

// The subagent under `id` ended its turn: a mission it led ends with it, but
// not while a subagent of the mission still runs (`busy`: one the engine
// lists that Dungeon may not have seen yet), nor, if done, before it has been
// quiet for SETTLE_MS (settleLed ends it then). A leader whose steps run in
// the background ends its turn as it sends them, and is woken by their reports.
export function endLed(missions: readonly Mission[], id: string, outcome: Mission['outcome'], at: number, busy = false): Mission[] | undefined {
  const m = missions.find(x => x.leader?.id === id)
  if (!m || m.endedAt !== undefined || busy || runsOf([m]).some(r => r.id !== id && r.status === 'running' && !r.awaiting) || !calm(m, outcome, at)) return undefined
  const end = endOf(m, outcome, at)
  return missions.map(x => (x === m ? settled({ ...x, endedAt: end, outcome }, end) : x))
}

// Missions whose leader has ended its turn and that nothing else of runs any
// more end now, as their leader did, once quiet for SETTLE_MS: what kept one
// going (a step, a step's own helper) ended after the leader's last turn.
export function settleLed(missions: readonly Mission[], at: number): Mission[] | undefined {
  const outcome = (r: SquadRun): Mission['outcome'] => (r.status === 'completed' ? 'done' : r.status === 'stopped' ? 'stopped' : 'error')
  const due = (m: Mission) =>
    m.leader !== undefined &&
    m.endedAt === undefined &&
    m.leader.status !== 'running' &&
    !runsOf([m]).some(r => r.status === 'running' && !r.awaiting) &&
    calm(m, outcome(m.leader), at)
  if (!missions.some(due)) return undefined
  return missions.map(m => {
    if (!due(m)) return m
    const how = outcome(m.leader!)
    const end = endOf(m, how, at)
    return settled({ ...m, endedAt: end, outcome: how }, end)
  })
}

// A mission that ended: a run still awaiting its background work is done
// with it (its leader had its report and went on).
const settled = (m: Mission, at: number): Mission =>
  mapRuns(m, r => (r.awaiting && r.status === 'running' ? { ...r, status: 'completed', awaiting: false, endedAt: r.endedAt ?? at } : r))

// Each run of a mission (its leader's, its steps', their helpers', its
// others') through `fn`.
export function mapRuns(m: Mission, fn: (r: SquadRun) => SquadRun): Mission {
  return {
    ...m,
    waves: m.waves.map(w => ({ ...w, steps: w.steps.map(s => ({ ...s, ...(s.run ? { run: fn(s.run) } : {}), ...(s.helpers ? { helpers: s.helpers.map(fn) } : {}) })) })),
    others: m.others.map(fn),
    ...(m.leader ? { leader: fn(m.leader) } : {}),
  }
}

// The subagent under `id` is at work again (a leader woken by its steps'
// reports): running once more, and its mission with it.
export function reviveRun(missions: readonly Mission[], id: string): Mission[] | undefined {
  const i = missions.findIndex(m => runsOf([m]).some(r => r.id === id))
  if (i < 0) return undefined
  const m = missions[i]!
  const r = runsOf([m]).find(x => x.id === id)
  if (m.endedAt === undefined && r?.status === 'running' && !r.awaiting) return undefined
  const { endedAt: _, outcome: __, ...rest } = m
  const back = (r: SquadRun): SquadRun => {
    if (r.id !== id) return r
    const { endedAt: _e, awaiting: _a, ...live } = r
    return { ...live, status: 'running' }
  }
  return missions.map((x, k) => (k !== i ? x : mapRuns(rest as Mission, back)))
}

// Whether Dungeon should still look for subagents in the engine's list: a
// mission with a leader is going, or ended within `within` ms (its leader may
// yet be woken).
export const watching = (missions: readonly Mission[], now: number, within: number): boolean =>
  missions.some(m => m.leader !== undefined && (m.endedAt === undefined || now - m.endedAt < within))

// What the engine's agent list says of a run: undefined while it still runs.
export function statusOfAgent(status: string): RunStatus | undefined {
  if (status === 'completed') return 'completed'
  if (status === 'failed') return 'failed'
  if (status === 'killed') return 'stopped'
  return undefined
}

// `1m 05s`, `42s`, `1h 03m`.
export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m ${String(s % 60).padStart(2, '0')}s`
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m`
}

// What a model request's usage counts toward a run's tokens: all it took in,
// cache read and written included, and all it gave out.
export type Usage = { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }
export const usageTokens = (u: Usage): number =>
  u.input_tokens + u.output_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens

// Every run's tokens in the missions, summed.
export const tokensOf = (missions: readonly Mission[]): number => runsOf(missions).reduce((n, r) => n + runTokens(r), 0)

// A run's tokens: its requests', else its turns'.
export const runTokens = (r: SquadRun): number => r.tokens || r.turnTokens || 0

// `812 tok`, `9.4k tok`, `31k tok`, `1.2M tok`.
export function tokensText(n: number): string {
  if (n < 1000) return `${n} tok`
  if (n < 10_000) return `${(n / 1000).toFixed(1)}k tok`
  if (n < 1_000_000) return `${Math.round(n / 1000)}k tok`
  return `${(n / 1_000_000).toFixed(1)}M tok`
}

// A mission's tokens beside its coin: `812`, `9.4K`, `124K`, `1.2M`.
export function coinText(n: number): string {
  if (n < 1000) return `${n}`
  if (n < 10_000) return `${(n / 1000).toFixed(1)}K`
  if (n < 1_000_000) return `${Math.round(n / 1000)}K`
  return `${(n / 1_000_000).toFixed(1)}M`
}

// A run's answer in a few lines: blank lines and markdown marks gone.
export function resultLines(text: string, lines: number): string[] {
  const kept = text
    .split('\n')
    .map(l => l.replace(/^\s*(#+|[-*>]|\d+\.)\s+/, '').replace(/[*`_]{1,3}/g, '').trim())
    .filter(l => l !== '')
  return kept.length > lines ? [...kept.slice(0, lines - 1), `${kept[lines - 1]} …`] : kept
}

// When a mission was sent, as this computer's clock read it: `2026-10-09 14:54`
// (`offset` minutes from UTC).
export function dateTimeText(at: number, offset: number): string {
  const d = new Date(at + offset * 60_000)
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`
}

files.hooks/dungeon.ts:
// Dungeon's scene, over its missions: on the left a wooden board keeping how
// many missions this session cleared; in the middle the main slime with its
// sword; on the right the dungeon's keep. While missions go on, the slime
// fights (a bubble at its upper left shows the fight, and how many are going)
// and the keep's portcullis is up, eyes glowing in the dark; with none, the
// slime rests on guard, its sword planted beside it and its eyes on the keep,
// whose portcullis is down.

import { modelInfo, pack, SKY } from './scene'
import type { Overlay } from './scene'

export const DUNGEON_ROWS = 8
const H = DUNGEON_ROWS * 2
const FLOOR_Y = H - 1

const FLOOR = { base: 0x3d3d4a, speck: 0x4a4a58 }
const BOARD = { edge: 0x6b4226, fill: 0x9c6b3f, text: 0xffe8c2, count: 0xffd23f }
const BUBBLE = { fill: 0xf5f5f5, text: 0x101018 }
const MONSTER = { body: 0x7b2cbf, eye: 0xff4d6d, hit: 0xff4d6d }
const SPARK = 0xffd23f
const SWORD = { blade: 0xdfe6ee, tip: 0xffffff, guard: 0xd4a017, grip: 0x6b4226 }
const KEEP = {
  stone: 0x6c757d,
  mortar: 0x495057,
  dark: 0x0b0b14,
  bars: 0x8d8d99,
  eyes: 0xff4d6d,
  bone: 0xe9e4d4,
  banner: 0xa4161a,
  trim: 0xd4a017,
  handle: 0x6b4226,
  flames: [0xff9f1c, 0xffd23f],
}
const EYE = 0x101018

// The main slime, larger than the world's: B body, H its gloss, D its rim, E
// eyes; on guard, settled a little lower, its eyes turned to the keep.
const SLIME = {
  awake: ['..BBBB..', '.BHHBBB.', 'BHBEBBEB', 'DBBBBBBD', 'DBBBBBBD', '.DDDDDD.'],
  guard: ['..BBBB..', '.BHHBBB.', 'BHBBEBEB', 'DBBBBBBD', '.DDDDDD.'],
}
// The board's count, in pixels: 3x5 digits.
const DIGITS = [
  ['###', '#.#', '#.#', '#.#', '###'],
  ['.#.', '##.', '.#.', '.#.', '###'],
  ['###', '..#', '###', '#..', '###'],
  ['###', '..#', '###', '..#', '###'],
  ['#.#', '#.#', '###', '..#', '..#'],
  ['###', '#..', '###', '..#', '###'],
  ['###', '#..', '###', '#.#', '###'],
  ['###', '..#', '.#.', '.#.', '.#.'],
  ['###', '#.#', '###', '#.#', '###'],
  ['###', '#.#', '###', '..#', '###'],
]

// Where the board stands, and the widths of the board, the keep and the
// bubble; the slime with its sword.
const BOARD_X = 1
const BOARD_W = 11
const KEEP_W = 11
const BUBBLE_W = 8
const HERO_W = SLIME.awake[0]!.length + 2

// The scene's frame of the fight: one of four, turning every few ticks.
export const fightFrame = (tick: number) => Math.floor(tick / 3) % 4

// `going`: the missions not yet ended (0: none, the slime rests on guard); `cleared`:
// those done this session; `model`: the main slime's, for its color.
export function dungeonFrame(columns: number, tick: number, model: string, going: number, cleared: number): string {
  const w = Math.max(1, Math.min(512, columns))
  const px = new Uint32Array(w * H).fill(SKY)
  const overlays: Overlay[] = []
  const put = (x: number, y: number, color: number) => {
    if (x >= 0 && x < w && y >= 0 && y < H) px[y * w + x] = color
  }
  const text = (x: number, row: number, s: string, fg: number, bg: number) => [...s].forEach((ch, i) => overlays.push({ col: x + i, row, ch, fg, bg }))
  const fighting = going > 0
  const f = fighting ? fightFrame(tick) : 0
  const hit = f % 2 === 1
  // The board at the left, the keep at the right edge (pushed past it when
  // the pane is too narrow for all), the slime midway between them.
  const boardR = BOARD_X + BOARD_W - 1
  const g = Math.max(w - KEEP_W, boardR + HERO_W)
  const sx = boardR + 1 + Math.max(0, Math.floor((g - boardR - 1 - HERO_W) / 2))
  const sr = sx + SLIME.awake[0]!.length - 1

  // The floor, all the pane's width.
  for (let x = 0; x < w; x++) put(x, FLOOR_Y, x % 5 === 0 ? FLOOR.speck : FLOOR.base)

  // The board: a plank on two posts, CLEARED over the count.
  for (let y = 1; y <= 11; y++)
    for (let x = BOARD_X; x <= boardR; x++) put(x, y, y === 1 || y === 11 || x === BOARD_X || x === boardR ? BOARD.edge : BOARD.fill)
  for (let y = 12; y < FLOOR_Y; y++) (put(BOARD_X + 2, y, BOARD.edge), put(boardR - 2, y, BOARD.edge))
  text(BOARD_X + 2, 1, 'CLEARED', BOARD.text, BOARD.fill)
  // The count under it in two pixel digits (`03`; 99 past that), a pixel
  // clear of the words above and of the board's edge all round.
  const count = String(Math.min(cleared, 99)).padStart(2, '0')
  const cx = BOARD_X + 2
  ;[...count].forEach((d, i) =>
    DIGITS[Number(d)]!.forEach((row, dy) => [...row].forEach((c, dx) => c === '#' && put(cx + i * 4 + dx, 5 + dy, BOARD.count))),
  )

  // The keep: a battlemented wall of bricks, a skull over its arched door, a
  // banner and a torch each side, and a portcullis, up while missions go on.
  const door = (x: number, y: number) => y >= 8 && x >= g + 3 && x <= g + 7 && !(y === 8 && (x === g + 3 || x === g + 7))
  for (let y = 1; y < FLOOR_Y; y++) {
    for (let x = g; x < g + KEEP_W; x++) {
      const dx = x - g
      if (y === 1 && (dx === 2 || dx === 3 || dx === 7 || dx === 8)) continue
      const mortar = y === 2 || y % 3 === 0 || (dx + (Math.floor(y / 3) % 2) * 2) % 4 === 0
      put(x, y, door(x, y) ? KEEP.dark : mortar ? KEEP.mortar : KEEP.stone)
    }
  }
  // The portcullis: its bars down to the floor, or drawn up to the arch.
  for (const bx of [g + 4, g + 6]) for (let y = 9; y < (fighting ? 11 : FLOOR_Y); y++) put(bx, y, KEEP.bars)
  if (!fighting) for (let x = g + 3; x <= g + 7; x++) put(x, 11, KEEP.bars)
  // Something waits in the dark while missions go on.
  if (fighting && f !== 3) (put(g + 4, 12, KEEP.eyes), put(g + 6, 12, KEEP.eyes))
  // The skull over the door.
  for (let x = g + 4; x <= g + 6; x++) put(x, 4, KEEP.bone)
  put(g + 4, 5, KEEP.dark)
  put(g + 5, 5, KEEP.bone)
  put(g + 6, 5, KEEP.dark)
  put(g + 4, 6, KEEP.bone)
  put(g + 6, 6, KEEP.bone)
  // Banners, swallow-tailed, and torches under them.
  for (const bx of [g + 1, g + 8]) {
    put(bx, 3, KEEP.trim)
    put(bx + 1, 3, KEEP.trim)
    for (let y = 4; y <= 6; y++) (put(bx, y, KEEP.banner), put(bx + 1, y, KEEP.banner))
    put(bx, 7, KEEP.banner)
  }
  for (const tx of [g + 1, g + 9]) {
    put(tx, 11, KEEP.handle)
    put(tx, 10, KEEP.flames[(Math.floor(tick / 2) + tx) % 2]!)
    if (fighting && f !== 3) put(tx, 9, KEEP.flames[1]!)
  }

  // The slime: hopping as it fights, else resting on guard.
  const info = modelInfo(model)
  const colors: Record<string, number> = { B: info.body, H: info.light, D: info.dark, E: EYE }
  const lift = hit ? 1 : 0
  const sprite = fighting ? SLIME.awake : SLIME.guard
  const top = FLOOR_Y - sprite.length - lift
  sprite.forEach((row, dy) => [...row].forEach((c, dx) => colors[c] !== undefined && put(sx + dx, top + dy, colors[c]!)))

  // The sword: in its right hand, upright or swung toward the keep; at rest,
  // planted in the ground at its side, its hilt to hand.
  const hx = sr + 1
  if (!fighting) {
    put(hx, FLOOR_Y - 8, SWORD.guard)
    put(hx, FLOOR_Y - 7, SWORD.grip)
    for (let x = hx - 1; x <= hx + 1; x++) put(x, FLOOR_Y - 6, SWORD.guard)
    for (let y = FLOOR_Y - 5; y < FLOOR_Y; y++) put(hx, y, SWORD.blade)
  } else {
    const hand = FLOOR_Y - 3 - lift
    put(hx, hand, SWORD.grip)
    if (hit) {
      put(hx - 1, hand - 1, SWORD.guard)
      put(hx + 1, hand + 1, SWORD.guard)
      for (let i = 1; i <= 5; i++) put(hx + i, hand - i, i === 5 ? SWORD.tip : SWORD.blade)
    } else {
      put(hx, hand + 1, SWORD.guard)
      for (let x = hx - 1; x <= hx + 1; x++) put(x, hand - 1, SWORD.guard)
      for (let y = hand - 7; y < hand - 1; y++) put(hx, y, y === hand - 7 ? SWORD.tip : SWORD.blade)
    }
  }

  // The bubble at its upper left: the fight, and how many are going.
  if (fighting) {
    const bx = Math.max(boardR + 2, sx - BUBBLE_W + 3)
    // It starts a row down from the pane's top, so that the tab above does
    // not run into it.
    for (let y = 1; y <= 7; y++) {
      for (let x = bx; x < bx + BUBBLE_W; x++) {
        if ((y === 1 || y === 7) && (x === bx || x === bx + BUBBLE_W - 1)) continue
        put(x, y, BUBBLE.fill)
      }
    }
    put(bx + BUBBLE_W - 2, 8, BUBBLE.fill)
    // A little slime lunges at a little monster; a spark where they meet.
    const ms = bx + 1 + (hit ? 1 : 0)
    for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]] as const) put(ms + dx, 4 + dy, info.body)
    const mx = bx + 4
    for (let y = 3; y <= 5; y++) for (let x = mx; x <= mx + 2; x++) put(x, y, hit ? MONSTER.hit : MONSTER.body)
    put(mx + 1, 4, hit ? BUBBLE.fill : MONSTER.eye)
    if (hit) for (const [x, y] of [[mx, 3], [mx - 1, 4], [mx, 4], [mx + 1, 4], [mx, 5]] as const) put(x, y, SPARK)
    const n = `×${Math.min(going, 99)}`
    text(bx + Math.floor((BUBBLE_W - n.length) / 2), 3, n, BUBBLE.text, BUBBLE.fill)
  }

  return pack(px, w, overlays, DUNGEON_ROWS)
}

files.hooks/summary.ts:
// A subagent's task summary laid out for the Party: wrapped to
// the pane's width so every line after the first hangs under the first's text.

// The model has its own line above, so a family name in the task's words
// (`Haiku test 1`, `Sonnet: review`) is left out of the summary.
export function cleanSummary(text: string): string {
  return text.replace(/\b(fable|opus|sonnet|haiku)\b:?/gi, '').replace(/\s+/g, ' ').trim() || 'subagent'
}

// Terminal cells a character takes: CJK and full-width forms take two.
const WIDE = /[ᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦]/
const cells = (text: string) => [...text].reduce((n, ch) => n + (WIDE.test(ch) ? 2 : 1), 0)

// Words break at spaces; a wide character is a word of its own, so CJK text
// wraps anywhere; a word longer than a line is split where the line ends.
function units(text: string): string[] {
  return text.match(/[ᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦]|[^\sᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦]+|\s+/g) ?? []
}

export function wrapSummary(text: string, width: number, maxLines = 3): string[] {
  const lines: string[] = []
  let line = ''
  const push = () => {
    lines.push(line.trimEnd())
    line = ''
  }
  for (const unit of units(text)) {
    if (/^\s+$/.test(unit)) {
      if (line !== '') line += ' '
      continue
    }
    let rest = unit
    while (rest !== '') {
      const room = width - cells(line)
      if (cells(rest) <= room) {
        line += rest
        rest = ''
      } else if (line.trim() !== '' && cells(rest) <= width) {
        push()
      } else {
        // Split what does not fit even on a line of its own.
        let head = ''
        for (const ch of rest) {
          if (cells(head + ch) > room) break
          head += ch
        }
        if (head === '') {
          push()
          continue
        }
        line += head
        rest = rest.slice(head.length)
        push()
      }
    }
  }
  if (line.trim() !== '') push()

  if (lines.length <= maxLines) return lines
  const kept = lines.slice(0, maxLines)
  let last = kept[maxLines - 1]!
  while (last !== '' && cells(last) + 1 > width) last = [...last].slice(0, -1).join('')
  kept[maxLines - 1] = `${last.trimEnd()}…`
  return kept
}

// The session's name from `grep -o` over its transcript, one
// `"customTitle":"…"` or `"aiTitle":"…"` a line, oldest first: the last name
// /rename gave wins over any Claude Code made up.
export function titleFrom(lines: string): string | undefined {
  let custom: string | undefined
  let made: string | undefined
  for (const line of lines.split('\n')) {
    const m = line.match(/^"(customTitle|aiTitle)":(".*")$/)
    if (!m) continue
    let value: string
    try {
      value = JSON.parse(m[2]!) as string
    } catch {
      continue
    }
    if (m[1] === 'customTitle') custom = value
    else made = value
  }
  return custom ?? made
}

// The sign's [≡] list: the project's other sessions, newest first, that the
// person has typed into (a `"type":"user"` line among what grep found), each
// by the name titleFrom reads, else when it was last written.
export type RecentSession = { id: string; title: string; at: number }
export function recentFrom(
  found: readonly { id: string; at: number; lines: string }[],
  current: string,
  max: number,
  untitled: (at: number) => string,
): RecentSession[] {
  return found
    .filter(f => f.id !== current && f.lines.includes('"type":"user"'))
    .sort((a, b) => b.at - a.at)
    .slice(0, max)
    .map(f => ({ id: f.id, title: titleFrom(f.lines) ?? untitled(f.at), at: f.at }))
}

// How long ago, as a list row says it: `now`, `5m`, `3h`, `2d`.
export function agoText(at: number, now: number): string {
  const s = Math.max(0, Math.floor((now - at) / 1000))
  if (s < 60) return 'now'
  if (s < 3600) return `${Math.floor(s / 60)}m`
  if (s < 86400) return `${Math.floor(s / 3600)}h`
  return `${Math.floor(s / 86400)}d`
}

files.hooks/freshness.ts:
// Is this dashboard behind GitHub? An install (`/plugin install`) records the
// commit it came from; that is compared with the newest commit on main. A copy
// loaded from a folder has no such record, so its version is compared with
// the version main's manifest declares instead.

export const REMOTE_SHA_URL = 'https://api.github.com/repos/egan-wu/slime-dashboard/commits/main'
export const REMOTE_MANIFEST_URL = 'https://raw.githubusercontent.com/egan-wu/slime-dashboard/main/.claude-plugin/plugin.json'

type InstallRecord = { gitCommitSha?: string; lastUpdated?: string }

// The commit of the newest install of `pluginId` in installed_plugins.json's
// text; undefined when it is not installed or the text does not parse.
export function installedSha(recordText: string, pluginId: string): string | undefined {
  try {
    const records = (JSON.parse(recordText) as { plugins?: Record<string, InstallRecord[]> }).plugins?.[pluginId] ?? []
    const newest = [...records].sort((a, b) => (b.lastUpdated ?? '').localeCompare(a.lastUpdated ?? ''))[0]
    return newest?.gitCommitSha
  } catch {
    return undefined
  }
}

// GitHub answers a bare commit hash when asked for `application/vnd.github.sha`.
export function remoteSha(text: string): string | undefined {
  const sha = text.trim()
  return /^[0-9a-f]{40}$/.test(sha) ? sha : undefined
}

export function manifestVersion(text: string): string | undefined {
  try {
    const version = (JSON.parse(text) as { version?: unknown }).version
    return typeof version === 'string' ? version : undefined
  } catch {
    return undefined
  }
}

files.hooks/vitals.ts:
// The slime's vitals, read from the session's usage figures.
//
// On a Pro or Max subscription HP is what is left of the seven-day limit and
// MP what is left of the five-hour one. Anywhere else (an API key, an
// enterprise seat) there is no such window to read, and HP stays full. CP is
// how full the context window is, its capacity.

export type Plan = 'subscription' | 'api'
export type Vitals = {
  plan: Plan
  // Whole percentages left, 0 to 100.
  hp: number
  mp: number
  // The context window's fill as a whole percentage; -1 before the first reading.
  cp: number
}

export const FULL: Vitals = { plan: 'api', hp: 100, mp: 100, cp: -1 }

type Window = { kind: string; percentUsed: number }

const left = (used: number | undefined) =>
  used === undefined ? 100 : Math.max(0, Math.min(100, Math.round(100 - used)))

// A subscription reports its five-hour and seven-day windows; an API key or
// an enterprise seat reports neither.
export function vitalsOf(rateLimits: readonly Window[], contextPercent: number | undefined): Vitals {
  const used = (kind: string) => rateLimits.find(w => w.kind === kind)?.percentUsed
  const isSubscription = used('five_hour') !== undefined || used('seven_day') !== undefined
  const cp = contextPercent === undefined ? -1 : Math.max(0, Math.min(100, Math.round(contextPercent)))
  return isSubscription
    ? { plan: 'subscription', hp: left(used('seven_day')), mp: left(used('five_hour')), cp }
    : { plan: 'api', hp: 100, mp: 100, cp }
}

// Out of HP, or on a subscription out of MP: the slime is down until a limit resets.
export const isDown = (v: Vitals) => v.hp <= 0 || (v.plan === 'subscription' && v.mp <= 0)

export type Eyes = 'x' | '><' | 'TT'
// `ask`: the session waits on the person (a permission prompt, a question),
// so the troop holds still with a blinking question mark over the main slime.
// `potions`: the pools that ran dry, each shown as a flashing potion in a
// ring at the main slime's upper left: blue for MP, red for HP.
export type Potion = 'hp' | 'mp'
// `unloading`: the context is compacting; the slime wakes and a flashing
// ring with a sack and a green down arrow stands where the potions do.
// `respawn`: ticks since the Skill Box's Respawn cleared the session.
// `warming`: Cache Warming is on, so the slime stays awake (standing still
// while idle) instead of falling asleep; `camp`: where its campfire burns
// (the screen column of its left edge), absent when there is none;
// `campAge`: ticks since it was set, while the slime spits a log and a flame.
export type Face = { eyes?: Eyes; vein?: boolean; down?: boolean; ask?: boolean; potions?: Potion[]; unloading?: boolean; respawn?: number; warming?: boolean; embers?: boolean; camp?: number; campAge?: number }

// Down: it stops with crossed-out eyes. Walking with a full head: squinting
// from 50%, a vein beside its head from 70%, in tears from 90%.
export function faceOf(v: Vitals, walking: boolean): Face {
  if (isDown(v)) {
    const potions: Potion[] = []
    if (v.plan === 'subscription' && v.mp <= 0) potions.push('mp')
    if (v.hp <= 0) potions.push('hp')
    return { eyes: 'x', down: true, potions }
  }
  if (!walking || v.cp < 50) return {}
  return { eyes: v.cp >= 90 ? 'TT' : '><', vein: v.cp >= 70 }
}

// How many of `cells` a bar fills for a percentage.
export const filledOf = (percent: number, cells: number) =>
  percent < 0 ? 0 : Math.max(0, Math.min(cells, Math.round((percent / 100) * cells)))

files.hooks/layout.ts:
// The pane's sections, which Setting's Display can hide and its Order can
// arrange; Setting itself always stays last and shown, so anything hidden or
// moved can always be brought back.

export const SECTIONS = [
  { id: 'session', label: 'Session' },
  { id: 'stats', label: 'HP / MP / CP' },
  { id: 'scene', label: 'Slime' },
  { id: 'models', label: 'Model buttons' },
  { id: 'passive', label: 'Passive' },
  { id: 'property', label: 'Property' },
  { id: 'skills', label: 'Skill Box' },
  { id: 'tree', label: 'Party Combo' },
  { id: 'monitor', label: 'Party' },
  { id: 'events', label: 'Event Message' },
  { id: 'journal', label: 'Journal' },
] as const

export type SectionId = (typeof SECTIONS)[number]['id']
export const DEFAULT_ORDER: SectionId[] = SECTIONS.map(s => s.id)

// A kept order, with anything unknown or repeated dropped and any section it
// lacks (one added since it was kept) put in at its default place.
export function orderFrom(value: unknown): SectionId[] {
  const known = new Set<string>(DEFAULT_ORDER)
  const kept = Array.isArray(value) ? value.filter((v): v is SectionId => typeof v === 'string' && known.has(v)) : []
  const order = [...new Set(kept)]
  DEFAULT_ORDER.forEach((id, i) => {
    if (!order.includes(id)) order.splice(Math.min(i, order.length), 0, id)
  })
  return order
}

// The order with `id` swapped with its neighbor `by` (-1 up, 1 down); at
// either end it stays put.
export function moveSection(order: SectionId[], id: SectionId, by: -1 | 1): SectionId[] {
  const at = order.indexOf(id)
  const to = at + by
  if (at < 0 || to < 0 || to >= order.length) return order
  const next = [...order]
  next[at] = order[to]!
  next[to] = id
  return next
}

